const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const PHONE_RE = /^\+?[0-9\s\-().]{7,}$/;

function FormField({ label, name, type = "text", value, onChange, onBlur, error, required, optional, helper, placeholder, autoComplete }) {
  const errorId = `${name}-error`;
  const helperId = `${name}-helper`;
  const describedBy = [error ? errorId : null, helper ? helperId : null].filter(Boolean).join(" ") || undefined;

  return (
    <div className="form-field">
      <div className="label-row">
        <label htmlFor={name}>{label}{required && <span aria-hidden="true" style={{ color: "var(--error)", marginLeft: 2 }}>*</span>}</label>
        {optional && <span className="optional">Optional</span>}
      </div>
      <input
        id={name}
        name={name}
        type={type}
        value={value}
        onChange={onChange}
        onBlur={onBlur}
        placeholder={placeholder}
        autoComplete={autoComplete}
        aria-invalid={!!error}
        aria-describedby={describedBy}
        aria-required={required || undefined}
        className={error ? "invalid" : ""}
      />
      {helper && !error && <div id={helperId} className="helper">{helper}</div>}
      {error && <div id={errorId} className="error-message" role="alert">{error}</div>}
    </div>
  );
}

function ContactForm() {
  const [values, setValues] = useState({ fullName: "", email: "", phone: "" });
  const [errors, setErrors] = useState({});
  const [touched, setTouched] = useState({});
  const [submitted, setSubmitted] = useState(false);

  const validate = (vals) => {
    const e = {};
    if (!vals.fullName.trim()) e.fullName = "Full name is required.";
    else if (vals.fullName.trim().length < 2) e.fullName = "Please enter your full name.";

    if (!vals.email.trim()) e.email = "Email address is required.";
    else if (!EMAIL_RE.test(vals.email.trim())) e.email = "Please enter a valid email address.";

    if (vals.phone.trim() && !PHONE_RE.test(vals.phone.trim())) {
      e.phone = "Please enter a valid phone number.";
    }
    return e;
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    const next = { ...values, [name]: value };
    setValues(next);
    if (touched[name]) {
      setErrors(validate(next));
    }
  };

  const handleBlur = (e) => {
    const { name } = e.target;
    setTouched((t) => ({ ...t, [name]: true }));
    setErrors(validate(values));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const eMap = validate(values);
    setErrors(eMap);
    setTouched({ fullName: true, email: true, phone: true });
    if (Object.keys(eMap).length === 0) {
      setSubmitted(true);
      setValues({ fullName: "", email: "", phone: "" });
      setTouched({});
    }
  };

  return (
    <div className="page">
      <main className="card">
        <div className="eyebrow">Support</div>
        <h1>Get in touch</h1>
        <p className="subtitle">Have a question or need help? Send us a message and our team will get back to you shortly.</p>

        {submitted && (
          <div className="success-banner" role="status">
            Thanks! Your message has been received. We'll be in touch soon.
          </div>
        )}

        <form noValidate onSubmit={handleSubmit}>
          <FormField
            label="Full name"
            name="fullName"
            value={values.fullName}
            onChange={handleChange}
            onBlur={handleBlur}
            error={touched.fullName ? errors.fullName : undefined}
            required
            placeholder="Jane Doe"
            autoComplete="name"
          />
          <FormField
            label="Email address"
            name="email"
            type="email"
            value={values.email}
            onChange={handleChange}
            onBlur={handleBlur}
            error={touched.email ? errors.email : undefined}
            required
            placeholder="you@example.com"
            autoComplete="email"
          />
          <FormField
            label="Phone number"
            name="phone"
            type="tel"
            value={values.phone}
            onChange={handleChange}
            onBlur={handleBlur}
            error={touched.phone ? errors.phone : undefined}
            optional
            helper="Format: +1 (555) 123-4567 — include country code if outside the US."
            placeholder="+1 (555) 123-4567"
            autoComplete="tel"
          />
          <button type="submit">Send message</button>
        </form>
      </main>
    </div>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<ContactForm />);
